import hmac
import hashlib

def verify_payment_signature(razorpay_order_id: str, razorpay_payment_id: str, razorpay_signature: str, key_secret: str) -> bool:
    """Cryptographically verify payment signature generated by Razorpay Checkout."""
    msg = f"{razorpay_order_id}|{razorpay_payment_id}".encode("utf-8")
    expected_sig = hmac.new(key_secret.encode("utf-8"), msg, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_sig, razorpay_signature)

def verify_webhook_signature(raw_body: bytes, razorpay_signature: str, webhook_secret: str) -> bool:
    """
    Cryptographically verify webhook event authenticity using raw byte stream.
    CRITICAL: Never deserialize payload before HMAC computation.
    """
    expected_sig = hmac.new(webhook_secret.encode("utf-8"), raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_sig, razorpay_signature)
